def load() -> pd.DataFrame:
    file_path = "data/biomedical/input/1-s2.0-S0092867420301070-mmc2.xlsx"
    xls = pd.ExcelFile(file_path)
    sheets = {}
    for sheet in xls.sheet_names:
        sheets[sheet] = pd.read_excel(file_path, sheet_name=sheet)
    return pd.DataFrame({'Sheet': list(sheets.keys()), 'Data': list(sheets.values())})

def process(load_global_proteomics) -> pd.DataFrame:
    df = load_global_proteomics[load_global_proteomics['protein'] == 'PLK1'].copy()
    return df

def process(load_phospho_proteomics) -> pd.DataFrame:
    df = load_phospho_proteomics[load_phospho_proteomics['protein'] == 'CHEK2-S163'].copy()
    return df
